// One live Telegram line per visitor per day, and one more when a new visitor
// turns out human. A first look only: the Bot Detector judges the whole day overnight.
// Your own networks, as address prefixes. Set in the n8n UI, never in the public copy.
const SELF_NETS = ['YOUR_HOME_NET_PREFIX.'];
const v = $('Visit Webhook').first().json.body || {};
const ip = String(v.ip || '');
if (!ip || SELF_NETS.some((net) => ip.startsWith(net))) return [];

// Who was already announced today; yesterday's list is dropped on the first event of a day.
const day = String(v.ts || new Date().toISOString()).slice(0, 10);
const memory = $getWorkflowStaticData('global');
if (!memory.told || memory.told.day !== day) memory.told = { day, visitors: {} };
const was = memory.told.visitors[ip] || '';

const where = [v.city, v.country].filter(Boolean).join(', ') || 'unknown place';
const ua = String(v.ua || '');
const bot = Boolean(v.flag) || !/mozilla\//i.test(ua);
// A link click is stored as "label → href"; a bare control has no arrow and went nowhere.
const [label, href] = String(v.target || '').split(' → ');
const clicked = v.event !== 'pageview' && Boolean(href);
let from = '';
try { from = v.referrer ? new URL(v.referrer).hostname.replace(/^www\./, '') : ''; } catch { from = String(v.referrer).slice(0, 40); }

let text = '';
if (!was && bot) {
  const name = (ua.match(/[\w.-]*(bot|crawler|spider|indexer|fetcher)[\w./-]*/i) || [])[0] || v.flag || 'no browser named';
  text = `🤖 Bot · ${name} · ${where} · ${v.path || '/'}`;
  memory.told.visitors[ip] = 'bot';
} else if (!was) {
  text = `🆕 New visitor · ${where} · ${v.path || '/'}` + (from ? ` · from ${from}` : '');
  memory.told.visitors[ip] = 'new';
} else if (was === 'new' && clicked) {
  text = `🙋 Likely human · ${where} · clicked “${label.trim()}”`;
  memory.told.visitors[ip] = 'human';
}
return text ? [{ json: { text } }] : [];
